import { View, Text, Pressable, FlatList, StyleSheet } from "react-native";
import { createContext, useContext, useState } from "react";
import { registerRootComponent } from "expo";

const CartContext = createContext(null);

function Shop() {
  const { addItem } = useContext(CartContext);
  return <Pressable nativeID="add" style={styles.b} onPress={() => addItem("Чихэвч")}><Text style={styles.t}>Чихэвч нэмэх</Text></Pressable>;
}
function Cart() {
  const { items } = useContext(CartContext);
  return <FlatList data={items} keyExtractor={(x, i) => String(i)} renderItem={({ item }) => <Text testID="row" style={styles.row}>{item}</Text>} />;
}

function App() {
  const [items, setItems] = useState([]);
  const addItem = (name) => setItems((prev) => [...prev, name]);
  return (
    <CartContext.Provider value={{ items, addItem }}>
      <View style={styles.s}><Shop /><Cart /></View>
    </CartContext.Provider>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 12, padding: 24 },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" }, t: { color: "#fff", fontWeight: "bold" },
  row: { padding: 12, backgroundColor: "#f1f5f9", borderRadius: 8 },
});

registerRootComponent(App);
